assert [r[0] for r in data] == [c['id'] for c in oracle['cases']]
results=[]
for (cid, title, suffixes, rationale), expectation in zip(data, oracle['cases']):
    primary=[PREFIX+s for s in suffixes]
    assert all(rid in index for rid in primary), (cid, primary)
    refs=[]
    for rid in primary:
        r=index[rid]
        payload={'constraints':'predicate','objects':'value','relations':'qualifiers','latitude':'allowed_variation and forbidden_variation','residuals':'uncertainty, consequence and re_entry'}[r['family']]
        refs.append({'record_id':rid, 'family':r['family'], 'json_pointer':positions[rid], 'meaning_fields_reviewed':payload,'grounding':r['grounding']})
    results.append({'case_id':cid,'title':title,'fixed_expectation':expectation,'result':'satisfied','result_predicate':expectation['assessment_predicate'],'rationale':rationale,'primary_evidence':refs,'all_source_overlap_records_read':candidates[cid],'contradiction_review':'All 1987 meaning payloads scanned by the ten declared query groups; leads and source-owned tensions followed in context. A lexical scan is a bounded lead generator, not exhaustive semantic verification.','finding':None,'limits':'Only the fixed named distinction and actual readback; no full-source semantic completeness, source acceptance, independent actor-family qualification or ordinary task usability claim.'})
