md=['# Fixed source-first case results','', 'This is a bound companion to REVIEW.md. All 44 situations and expectations below were fixed before model exposure. A result of **satisfied** answers only the fixed preservation predicate: the inspected representation preserves this source-owned distinction. It is not acceptance of the model, source, package or method. All named source files are frozen at common commit `35fb4824a064a84df5af214a0d0e2da597c18ac6`, package tree `7f2070b61c848b42b4dfb3af1e0ce53869de1aa1`.', '', 'Source paths are package-relative under `source/`. Lines are 1-based inclusive. Record suffixes below expand by prepending `' + PREFIX + '`. The frozen model ID is `' + model['id'] + '` and canonical SHA-256 is `691c4ab0d0993312a31e7e2371070ea4758fdf74b32862ff4d5a32d05af79fbf`. JSON pointers identify the exact record containers; the named meaning payload includes conditions, exceptions and uncertainty, not just a favourable sentence.', '', 'The pre-model oracle commitment is `2658e5ec3e0ad43d70e316e7727148db7e349caa104260c7b5d6ce395ab94ce9`. Original preparation commitment is `ed175c3f38490b079d6910d5d26f926769677b30c16371729705876df96892f0`. These are external proof-custody commitments, not links to bundled evidence.', '']
for r in results:
    md += ['## '+r['case_id']+' — '+r['title'],'','**Fixed situation and expected distinction:** '+r['fixed_expectation']['fixed_situation_and_expected_distinction_verbatim'],'','**Result:** satisfied for that preservation predicate. '+r['rationale'],'','**Source witnesses:**','']
    for w in r['fixed_expectation']['witnesses']:
        ranges=', '.join(str(s['start_line'])+'–'+str(s['end_line']) for s in w['segments'])
        md += ['- `'+w['path']+':'+ranges+'`; file SHA-256 `'+w['file_sha256']+'`.']
    md += ['','**Exact model evidence:**','']
    for e in r['primary_evidence']:
        md += ['- `'+e['record_id'].removeprefix(PREFIX)+'`, `'+e['json_pointer']+'`: '+e['meaning_fields_reviewed']+'.']
    md += ['','All '+str(len(r['all_source_overlap_records_read']))+' records overlapping this case\'s fixed source witnesses were read, with cross-model contradiction leads checked separately. No actionable defect was found for the fixed distinction.','']
(HERE/'CASES.md').write_text('\n'.join(md)+'\n')
print('cases',len(results),'unique_overlap_records',len({rid for r in results for rid in r['all_source_overlap_records_read']}),'primary_references',sum(len(r['primary_evidence']) for r in results))
